import { Vector3 } from 'three';
import type { CombatConfig, ZombieRank } from '../../data/types';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { Vehicle } from '../vehicle/Vehicle';
import type { Zombie } from '../zombies/Zombie';
import type { ZombiePool } from '../zombies/ZombiePool';
import type { KillReport } from './Weapons';

export interface ImpactEvent {
  zombie: Zombie;
  rank: ZombieRank;
  relativeSpeed: number;
  damageToZombie: number;
  damageToCar: number;
  killed: boolean;
  position: { x: number; y: number; z: number };
}

const relative = new Vector3();
const knockbackDir = new Vector3();

/** M1: seconds a zombie ignores its own AI movement after a melee knockback shove. */
const KNOCKBACK_STUN_SECONDS = 0.35;

/**
 * B4/B5: turns car-zombie contacts into damage. Impact damage to the zombie is
 * relative speed x car mass x factor; slow bumps just shove. Heavy ranks hurt the
 * car back, scaled by speed and reduced by armor inside Vehicle.applyDamage.
 */
export class RunOverSystem {
  /** From the Front Ram upgrade (D12): multiplies damage dealt to zombies on impact. */
  damageMultiplier = 1;
  /** From the Front Ram upgrade: scales impact damage the car takes. */
  selfDamageMultiplier = 1;
  /** M1: flat bonus damage from an equipped front-mounted melee weapon (0 = none equipped),
   *  dealt on every contact regardless of speed - unlike the ram's speed-scaled multiplier. */
  meleeDamage = 0;
  /** M1: horizontal knockback speed (m/s) from an equipped melee weapon (0 = none). */
  meleeKnockback = 0;
  /** M3: damage per second from an equipped Circular Saw, applied every tick a zombie stays
   *  in contact - distinct from the spike cluster's one-shot-per-contact-event damage. */
  sawDamagePerSecond = 0;
  /** Collider handles of zombies currently touching the car, tracked across steps so
   *  applySawDamage() can deal continuous damage rather than only reacting to new contacts. */
  private readonly touching = new Set<number>();

  /** M3: whether an equipped saw is actually grinding into something right now - for sound. */
  get sawActive(): boolean {
    return this.sawDamagePerSecond > 0 && this.touching.size > 0;
  }

  constructor(
    private readonly physics: PhysicsWorld,
    private readonly car: Vehicle,
    private readonly pool: ZombiePool,
    private readonly cfg: CombatConfig,
    private readonly carMass: number
  ) {}

  private readonly carVelocityBeforeStep = new Vector3();

  /**
   * Call right before physics.step(). Contact resolution flings a light zombie to the
   * car's speed within the step, so impact speed must come from the pre-step velocities.
   */
  beforeStep(): void {
    this.car.getLinearVelocity(this.carVelocityBeforeStep);
    for (const z of this.pool.active()) {
      const v = z.body.linvel();
      z.velocityBeforeStep.set(v.x, v.y, v.z);
    }
  }

  /** Call right after physics.step(). Returns one event per zombie the car started touching. */
  collectImpacts(): ImpactEvent[] {
    const events: ImpactEvent[] = [];
    const carHandle = this.car.collider.handle;
    this.physics.drainCollisions((h1, h2, started) => {
      const other = h1 === carHandle ? h2 : h2 === carHandle ? h1 : -1;
      if (other < 0) return;
      if (!started) {
        this.touching.delete(other);
        return;
      }
      this.touching.add(other);
      const zombie = this.pool.fromColliderHandle(other);
      if (!zombie || !zombie.isAlive()) return;
      events.push(this.resolve(zombie));
    });
    return events;
  }

  /**
   * M3: the Circular Saw's continuous damage, dealt every tick to every zombie still touching
   * the car (tracked via collectImpacts()'s start/stop events) rather than only on new contact.
   * Call once per Playing tick, after collectImpacts(). Self-heals stale handles (a despawned
   * zombie whose contact-stop event was missed) by dropping anything no longer alive.
   */
  applySawDamage(dt: number): KillReport[] {
    const kills: KillReport[] = [];
    if (this.sawDamagePerSecond <= 0 || this.touching.size === 0) return kills;
    for (const handle of this.touching) {
      const zombie = this.pool.fromColliderHandle(handle);
      if (!zombie || !zombie.isAlive()) {
        this.touching.delete(handle);
        continue;
      }
      if (zombie.takeDamage(this.sawDamagePerSecond * dt)) {
        const p = zombie.getPosition();
        kills.push({ zombie, position: { x: p.x, y: p.y, z: p.z } });
      }
    }
    return kills;
  }

  resolve(zombie: Zombie): ImpactEvent {
    const relativeSpeed = relative
      .copy(this.carVelocityBeforeStep)
      .sub(zombie.velocityBeforeStep)
      .length();

    let damageToZombie = 0;
    if (relativeSpeed >= this.cfg.runOverMinSpeed) {
      damageToZombie =
        relativeSpeed * this.carMass * this.cfg.runOverDamageFactor * this.damageMultiplier;
    }
    // M1: an equipped melee weapon adds flat damage on every contact, even a near-stationary one.
    damageToZombie += this.meleeDamage;
    const killed = damageToZombie > 0 ? zombie.takeDamage(damageToZombie) : false;

    if (this.meleeKnockback > 0 && !killed) {
      knockbackDir.copy(zombie.getPosition()).sub(this.car.getPosition());
      knockbackDir.y = 0;
      if (knockbackDir.lengthSq() > 1e-6) {
        knockbackDir.normalize();
        zombie.setHorizontalVelocity(
          knockbackDir.x * this.meleeKnockback,
          knockbackDir.z * this.meleeKnockback
        );
        zombie.knockbackTimeLeft = KNOCKBACK_STUN_SECONDS;
      }
    }

    const rawCarDamage =
      this.cfg.impactDamageToCar[zombie.rank] *
      Math.min(1, relativeSpeed / this.cfg.impactFullSpeed) *
      this.selfDamageMultiplier;
    const damageToCar = this.car.applyDamage(rawCarDamage);

    const p = zombie.getPosition();
    return {
      zombie,
      rank: zombie.rank,
      relativeSpeed,
      damageToZombie,
      damageToCar,
      killed,
      position: { x: p.x, y: p.y, z: p.z },
    };
  }
}
